//! Canonical-bytes fixtures: the entry body hash/signature and the SignetAuth
//! assertion bytes are pinned here, generated by this test and verified by
//! the JavaScript and Python checkers in `deploy/checks/`.
//!
//! Regenerate with UPDATE_FIXTURES=1 cargo test -p datu-core --test
//! canonical_vectors. Without it, the committed fixture must match byte for
//! byte, so a serialization change cannot slip through unnoticed.

use datu_core::auth::{sign_assertion, verify_assertion, AuthChallenge};
use datu_core::{CheckpointBody, EntryBody};
use ed25519_dalek::{Signer, SigningKey};
use serde_json::{json, Value};

const SEED: [u8; 32] = [7u8; 32];
const FIXTURE: &str = "tests/fixtures/canonical_vectors.json";

fn vectors() -> Value {
    let key = SigningKey::from_bytes(&SEED);
    let pubkey = hex::encode(key.verifying_key().as_bytes());

    let body = EntryBody {
        version: 1,
        author: pubkey.clone(),
        author_pq: "pq-fixture".into(),
        pq_alg: "mldsa65".into(),
        namespace: "gov.fixture".into(),
        seq: 3,
        prev: Some([2u8; 32]),
        refs: vec![[1u8; 32]],
        timestamp_ms: 1_700_000_000_000,
        payload: br#"{"n":3}"#.to_vec(),
    };
    let canonical = borsh::to_vec(&body).expect("entry body serializes");
    let id = *blake3::hash(&canonical).as_bytes();
    let sig = key.sign(&canonical);

    let challenge = AuthChallenge {
        rp_id: "app.example.com".into(),
        origin: "https://app.example.com".into(),
        nonce: [0xAB; 16],
        expires_at_ms: 1_700_000_060_000,
    };
    let auth_bytes = challenge.to_signed_bytes();
    let auth_sig = sign_assertion(&key, &challenge);
    assert!(verify_assertion(&key.verifying_key(), &challenge, &auth_sig).is_ok());

    let checkpoint = CheckpointBody {
        version: 1,
        signer: pubkey.clone(),
        signer_pq: "pq-fixture".into(),
        pq_alg: "mldsa65".into(),
        height: 0,
        prev: None,
        timestamp_ms: 1_700_000_100_000,
        entries_count: 4,
        entry_ids_root: [3u8; 32],
    };
    let cp_canonical =
        datu_core::Checkpoint::body_bytes(&checkpoint).expect("checkpoint body serializes");
    let cp_id = *blake3::hash(&cp_canonical).as_bytes();
    let cp_sig = key.sign(&cp_canonical);

    // Party signature: digest of canonical JSON. Built by hand, not via
    // sign(), because PartySignature::sign stamps now_ms() and a fixture
    // must not change between runs.
    let party_doc = datu_core::parties::SignedDocument::new(
        "land.title.application",
        json!({"parcel": "AB-123", "grantee": "acme-ltd", "nested": {"z": 1, "a": 2}}),
    );
    let party_role = "holder";
    let party_bytes = party_doc
        .signing_bytes(party_role, &pubkey)
        .expect("party signing bytes");
    let party_digest = party_doc.digest(party_role, &pubkey).expect("party digest");
    assert_eq!(party_digest, *blake3::hash(&party_bytes).as_bytes());
    let party_sig = key.sign(&party_digest);

    // End-to-end: the hand-built signature must pass SignedDocument::verify,
    // so the pinned digest and the verifier can never drift apart silently.
    let mut signed = party_doc.clone();
    signed.parties.push(datu_core::parties::PartySignature {
        role: party_role.into(),
        key: pubkey.clone(),
        ed_signature: hex::encode(party_sig.to_bytes()),
        pq_key: None,
        pq_signature: None,
        pq_alg: None,
        timestamp_ms: 1_700_000_200_000,
    });
    let roles = signed.verify().expect("party signature verifies");
    assert_eq!(roles, vec![(party_role.to_string(), pubkey.clone())]);

    json!({
        "key_seed_hex": hex::encode(SEED),
        "public_key_hex": pubkey,
        "entry": {
            "canonical_hex": hex::encode(&canonical),
            "id_hex": hex::encode(id),
            "signature_hex": hex::encode(sig.to_bytes()),
        },
        "auth": {
            "rp_id": challenge.rp_id,
            "origin": challenge.origin,
            "nonce_hex": hex::encode(challenge.nonce),
            "expires_at_ms": challenge.expires_at_ms,
            "canonical_hex": hex::encode(&auth_bytes),
            "signature_hex": hex::encode(auth_sig),
        },
        "party": {
            "v": party_doc.v,
            "kind": party_doc.kind,
            "doc": party_doc.doc,
            "role": party_role,
            "key": pubkey,
            "timestamp_ms": 1_700_000_200_000u64,
            "canonical_hex": hex::encode(&party_bytes),
            "digest_hex": hex::encode(party_digest),
            "signature_hex": hex::encode(party_sig.to_bytes()),
        },
        "checkpoint": {
            "height": checkpoint.height,
            "entries_count": checkpoint.entries_count,
            "entry_ids_root_hex": hex::encode(checkpoint.entry_ids_root),
            "canonical_hex": hex::encode(&cp_canonical),
            "id_hex": hex::encode(cp_id),
            "signature_hex": hex::encode(cp_sig.to_bytes()),
        },
    })
}

#[test]
fn canonical_vectors_are_stable() {
    let fresh = serde_json::to_string_pretty(&vectors()).unwrap();
    if std::env::var("UPDATE_FIXTURES").is_ok() {
        std::fs::write(FIXTURE, fresh + "\n").unwrap();
        return;
    }
    let committed = std::fs::read_to_string(FIXTURE).expect(
        "fixture missing: run UPDATE_FIXTURES=1 cargo test -p datu-core --test canonical_vectors",
    );
    assert_eq!(
        committed.trim_end(),
        fresh.trim_end(),
        "canonical bytes changed: if intentional, regenerate the fixture"
    );
}
